/**
 * 解析 - Grafana 告警
 */

// ======================= 可配置图标 =======================
// 默认 Grafana 图标（未命中下方系统专属图标，或对应项留空 "" 时统一使用）
const GRAFANA_DEFAULT_ICON = "https://cdn.jsdelivr.net/gh/selfhst/icons/png/grafana.png";

// 不同系统的专属图标配置：[匹配关键词数组（不区分大小写）, 图标网址]
// - 会同时匹配 alert.labels.grafana_folder 与 alert.labels.alertname，按从上到下的顺序优先命中；
// - 图标网址留空 "" 表示暂不启用该系统专属图标，自动回退到 GRAFANA_DEFAULT_ICON；
// - 想为某个系统设置独立 Logo，直接把你的 自建图床 或其它公网图片网址填进引号里即可。
const GRAFANA_SYSTEM_ICONS = [
    [["immortalwrt", "openwrt"], ""], // ImmortalWRT / OpenWrt 软路由（放 PVE 前面，避免被 PVE 抢先命中）
    [["unraid"], ""],                 // unRAID 服务器
    [["pve", "proxmox"], ""],         // Proxmox VE 宿主机
    [["synology", "dsm"], ""]         // 群晖 Synology NAS
    // 新增其它系统示例：
    // [["ubuntu", "debian"], "https://cdn.jsdelivr.net/gh/selfhst/icons/png/ubuntu.png"],
];
// =========================================================

const str = (v) => (v === null || v === undefined ? "" : String(v));
let testMode = false;
const utf8Bytes = (ch) => {
    const cp = ch.codePointAt(0);
    if (cp <= 0x7f) return 1;
    if (cp <= 0x7ff) return 2;
    if (cp <= 0xffff) return 3;
    return 4;
};
const clipUtf8 = (text, maxBytes, suffix = "") => {
    const s = str(text);
    let total = 0;
    for (const ch of s) total += utf8Bytes(ch);
    if (total <= maxBytes) return s;
    let suffixBytes = 0;
    for (const ch of suffix) suffixBytes += utf8Bytes(ch);
    const limit = Math.max(0, maxBytes - suffixBytes);
    let used = 0;
    let out = "";
    for (const ch of s) {
        const b = utf8Bytes(ch);
        if (used + b > limit) break;
        out += ch;
        used += b;
    }
    return out.trimEnd() + suffix;
};
const bark = (group, title, body, extra = {}) => {
    const fullTitle = clipUtf8(testMode ? `【🧪测试】 ${title}` : title, 240, "…");
    const safeBody = clipUtf8(body, 2800, "\n…（内容过长已截断）");
    const payload = { group, title: fullTitle, body: safeBody, action: "none" };
    for (const [key, value] of Object.entries(extra)) {
        if (value !== undefined && value !== null && value !== "") payload[key] = value;
    }
    return payload;
};
const fail = (reason, source) => [{ json: { unmatched: true, reason, source } }];

// 时间统一按 UTC+8 显示，不依赖 n8n 容器的 TZ 设置
const formatTimestamp = (value) => {
    const text = str(value).trim();
    if (!text || /^0001-01-01/.test(text)) return "";
    const d = new Date(text);
    if (Number.isNaN(d.getTime())) return text;
    const hasZone = /(?:Z|[+-]\d{2}:?\d{2})$/i.test(text);
    const t = hasZone ? new Date(d.getTime() + 8 * 3600 * 1000) : d;
    const year = hasZone ? t.getUTCFullYear() : t.getFullYear();
    const month = hasZone ? t.getUTCMonth() + 1 : t.getMonth() + 1;
    const day = hasZone ? t.getUTCDate() : t.getDate();
    const hour = hasZone ? t.getUTCHours() : t.getHours();
    const minute = hasZone ? t.getUTCMinutes() : t.getMinutes();
    const second = hasZone ? t.getUTCSeconds() : t.getSeconds();
    const p = (n) => String(n).padStart(2, "0");
    return `${year} 年 ${p(month)} 月 ${p(day)} 日 ${p(hour)} 时 ${p(minute)} 分 ${p(second)} 秒`;
};

const { kind, payload } = $input.first().json;
testMode = payload.__test === true;
if (kind !== "grafana") return [];

const alerts = Array.isArray(payload.alerts) ? payload.alerts : [];
if (!alerts.length) return fail("Grafana alerts 为空", "Grafana");

const DASH = "—";
const val = (value) => {
    const s = str(value).trim();
    return s || DASH;
};
const round2 = (value) => {
    const n = Number(value);
    if (!Number.isFinite(n)) return str(value);
    return String(Math.round(n * 100) / 100);
};

const firstUrl = (...values) => {
    for (const value of values) {
        const s = str(value).trim();
        if (/^https?:\/\//i.test(s)) return s;
    }
    return "";
};
const resolveGrafanaIcon = (labels = {}) => {
    const haystack = `${str(labels.grafana_folder)} ${str(labels.alertname)}`.toLowerCase();
    for (const [keywords, iconUrl] of GRAFANA_SYSTEM_ICONS) {
        const url = firstUrl(iconUrl);
        if (!url) continue;
        const list = Array.isArray(keywords) ? keywords : [keywords];
        if (list.some((kw) => kw && haystack.includes(str(kw).toLowerCase()))) {
            return url;
        }
    }
    return GRAFANA_DEFAULT_ICON;
};

const out = [];
for (const alert of alerts) {
    const labels = alert.labels || {};
    const annotations = alert.annotations || {};
    const icon = resolveGrafanaIcon(labels);
    const image = firstUrl(alert.imageURL, payload.imageURL);

    const status = str(alert.status).toLowerCase();
    const isResolved = status === "resolved" || status === "normal";
    let level;
    if (status === "firing") level = "critical";
    else if (isResolved) level = "active";
    else if (status === "pending") level = "passive";

    // Grafana 的详情在 summary / description（有的版本是 detail/message），
    // 查询失败时还会带 Error，逐个兜底，别再出现空的“异常详情”
    const summary = str(annotations.summary).trim();
    const description = str(annotations.description).trim();
    const errorText = str(annotations.Error).trim();
    let detailText =
        [summary, description].filter(Boolean).join("；") ||
        str(annotations.detail || annotations.message || errorText).trim() ||
        DASH;

    // values 的 key 是 Grafana 查询的 refId（A/B/C），对用户没意义，
    // 只取真正的数值（跳过 -1 和 0/1 这类条件值），再按告警类型补单位。
    const values = alert.values && typeof alert.values === "object" ? alert.values : {};
    const numeric = Object.values(values).filter((value) => typeof value === "number" && value !== -1);
    const meaningful = numeric.filter((value) => value !== 0 && value !== 1);
    const chosen = meaningful.length ? meaningful : numeric;
    const contextText = `${str(labels.alertname)} ${summary}`;
    const unit = /温度/.test(contextText) ? "°C" : /(使用率|占用|CPU|内存|磁盘|负载)/.test(contextText) ? "%" : "";
    const formattedValues = chosen.length
        ? chosen.map((value) => `${round2(value)}${unit}`).join("、")
        : "";
    const endsWithReached = /已达\s*$/.test(detailText);

    const title = isResolved
        ? `✅ ${val(labels.alertname)} 已恢复`
        : `⚠️ ${val(labels.alertname)}`;

    let body = "";
    if (isResolved) {
        body += "【状态】已恢复\n";
        if (endsWithReached) {
            if (formattedValues) body += `【当前数值】${formattedValues}\n`;
        } else if (detailText && detailText !== DASH) {
            body += `【原告警内容】${detailText}\n`;
        }
        body += `【报警时间】${val(formatTimestamp(alert.startsAt))}\n`;
        const resolvedAt = formatTimestamp(alert.endsAt);
        if (resolvedAt) body += `【恢复时间】${resolvedAt}\n`;
        body +=
            `\n📊在Grafana中查看📊 ${val(alert.dashboardURL)}\n` +
            `📊查看机器整体运行状态📊 ${val(alert.panelURL)}`;
    } else {
        if (endsWithReached) {
            detailText += formattedValues ? ` ${formattedValues}` : "（数值不可用）";
        }
        body =
            `【异常详情】${detailText}\n` +
            `【报警时间】${val(formatTimestamp(alert.startsAt))}\n`;
        // 错误只保留“类型”（冒号前面），完整报错太长不再转发
        const errorType = (errorText.split(/[:：]/)[0] || "").trim();
        if (errorType) {
            const shortError = errorType.length > 120 ? errorType.slice(0, 120) + "…" : errorType;
            body += `【错误】${shortError}\n`;
        }
        body +=
            `\n🛑关闭报警🛑 ${val(alert.silenceURL)}\n` +
            `📊在Grafana中查看📊 ${val(alert.dashboardURL)}\n` +
            `📊查看机器整体运行状态📊 ${val(alert.panelURL)}`;
    }

    out.push({
        json: {
            bark: bark("Grafana", title, body, { icon, image, level }),
            source: "Grafana"
        }
    });
}
return out;
